merge into ins_assigned iae1_0 using (values (?,?,?,?), (?,?,?,?), (?,?,?,?)) excluded(id,code,name,version) on (iae1_0.id=excluded.id) when matched and iae1_0.code=? and iae1_0.name=? then update set version=(iae1_0.version+cast(? as integer)),code=excluded.code,name=excluded.name when not matched then insert (id,code,name,version) values (excluded.id,excluded.code,excluded.name,excluded.version)
